// Writes src/editpage.js from edit/: the Worker serves the page from strings.
// Run after changing a file in edit/: node edit/build.mjs
import { readFileSync, writeFileSync } from "node:fs";

const read = (name) => readFileSync(new URL(name, import.meta.url), "utf8");
const tags = JSON.parse(readFileSync(new URL("../../contract/v1/tags.json", import.meta.url), "utf8")).tags;
const js = `const TAGS = ${JSON.stringify(tags)};\n${read("app.js")}`;
writeFileSync(new URL("../src/editpage.js", import.meta.url),
  "// Generated by edit/build.mjs from edit/. Do not edit.\n" +
  `export const EDIT_HTML = ${JSON.stringify(read("index.html"))};\n` +
  `export const EDIT_CSS = ${JSON.stringify(read("app.css"))};\n` +
  `export const EDIT_JS = ${JSON.stringify(js)};\n`);
